import{c as t,Q as o,j as d,m as c}from"./chunks/framework.g_l1frA7.js";const m=JSON.parse('{"title":"CSS & Design Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"developers/css.md","filePath":"developers/css.md","lastUpdated":null}'),a={name:"developers/css.md"};function s(n,e,r,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="css-design-conventions" tabindex="-1">CSS &amp; Design Conventions <a class="header-anchor" href="#css-design-conventions" aria-label="Permalink to &quot;CSS &amp; Design Conventions&quot;">​</a></h1><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>All UI color, spacing, radius, and shadow values live in <code>ui/src/styles/tokens.css</code>. Do not hardcode them in components.</p><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><code>--accent</code></td><td><code>#C9F950</code></td><td>Vivid lime — reserved for the single most important action</td></tr><tr><td><code>--accent-ink</code></td><td><code>#0A0F02</code></td><td>Text on accent</td></tr><tr><td><code>--accent-soft</code> / <code>--accent-line</code></td><td><code>rgba(201,249,80,…)</code></td><td>Calm tint for routine surfaces / borders</td></tr><tr><td><code>--surface</code> / <code>--surface-2</code> / <code>--elevated</code></td><td>Theme-dependent</td><td>Card surfaces</td></tr><tr><td><code>--line</code> / <code>--line-2</code></td><td>Theme-dependent</td><td>Hairlines — keep them thin</td></tr><tr><td><code>--ink</code> / <code>--ink-mute</code> / <code>--ink-faint</code></td><td>Theme-dependent</td><td>Text</td></tr><tr><td><code>--radius</code> / <code>--radius-lg</code></td><td><code>10px</code> / <code>14px</code></td><td>Card radii</td></tr><tr><td><code>--sans</code> / <code>--mono</code></td><td>Geist Variable</td><td>Font stacks</td></tr></tbody></table><p>Dark (<code>data-theme=&quot;dark&quot;</code>) is primary: <code>--bg: #08080B</code>, <code>--surface: #101015</code>. Light: <code>--bg: #F8F7F2</code>, <code>--surface: #FFFFFF</code>.</p><h2 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to &quot;Utilities&quot;">​</a></h2><p><code>ui/src/styles/app.css</code> defines shared classes. Prefer them over one-off styles:</p><ul><li><code>.card</code> <code>.chip</code> <code>.btn</code> <code>.tbl</code> <code>.stat</code> <code>.eyebrow</code> <code>.toolbar</code> <code>.stream</code> <code>.goal-bar</code></li><li><code>.money</code> — amounts that must blur in Privacy mode (<code>[data-privacy=&quot;on&quot;] .money</code>)</li></ul><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>Use tokens, not hex literals.</li><li>Reuse components (<code>ui/src/components/</code>) and the utility classes; do not invent a second card style.</li><li>Privacy-mode amounts must carry <code>&quot;money&quot;</code> — CSS blurs them automatically.</li><li>Motion: use expo easings (<code>--ease-out-expo</code>, <code>--ease-out-quart</code>), never bounce/elastic; respect <code>prefers-reduced-motion</code>.</li><li>Density via <code>data-density=&quot;cozy&quot;|&quot;compact&quot;</code> and <code>pointer: coarse</code> for touch targets.</li></ul><h2 id="docs-theme" tabindex="-1">Docs theme <a class="header-anchor" href="#docs-theme" aria-label="Permalink to &quot;Docs theme&quot;">​</a></h2><p>The VitePress theme at <code>docs/.vitepress/theme/</code> reuses the FinSight tokens as <code>--fs-*</code> and maps them to VitePress brand vars, so docs and app share the same accent and the same calm.</p><p>See also: <a href="/FinSight/developers/frontend">Frontend</a>, <a href="/FinSight/getting-started/privacy">Privacy &amp; Tokens</a>.</p>',13)])])}const p=t(a,[["render",s]]);export{m as __pageData,p as default};
